from robot import *

def flatten(items):
    flat = []
    for item in items:
        if isinstance(item, list):
            flat.extend(flatten(item))
        else:
            flat.append(item)
    return flat
move()
codes = flatten(scan())
say("Codes found:", len(codes))
for code in codes:
    unlock(code)
    move()
while not at_exit():
    move()
